function OverseaManageCatBallExchangeCell:Start()
    local BtnNode = self.BtnNode
    local BtnNodeAnimation = self.BtnNodeAnimation
    BtnNode.onClick = function()
        if self._clickCb then
            self._clickCb(self._data, self._isGoods, self)
        end
    end
    BtnNode.onPointerDown = function()
        BtnNodeAnimation:Play("UI_Common_ButtonPressed")
    end
    BtnNode.onPointerUp = function()
        BtnNodeAnimation:Play("UI_Common_ButtonIdle")
    end
    BtnNode.onPointerExit = function()
        BtnNodeAnimation:Play("UI_Common_ButtonIdle")
    end
    BtnNode.onLongPress = function(durationSeconds)
        if self._longPressCb then
            self._longPressCb(BtnNode, durationSeconds, self._data, self._isGoods, self)
        end
    end


    local BtnReduce          = self.BtnReduce
    local BtnReduceAnimation = self.BtnReduceAnimation
    BtnReduce.onClick = function()
        if self._clickBtnReduceCb then
            self._clickBtnReduceCb(self._data, self)
        end
    end
    BtnReduce.onPointerDown = function()
        BtnReduceAnimation:Play("UI_Common_ButtonPressed")
    end
    BtnReduce.onPointerUp = function()
