--region logic

---FreshUI
---@param data table {
---     vo : MaidCoffeeCatRollConfigVo | GoodsVo
---     quality: MaidCoffeeConstants.CatBallQuality
---     catData: CatEggDojo 非道具必有
---     goodsNum: number 道具必有
---}
function OverseaManageCatBallExchangeCell:FreshUI(data, playerCatId2Data)
    --- 判断道具 用 goodsNum 或 MaidCoffeeConstants.CatBallQuality.Theme 都行
    local goodsNum = data.goodsNum
    local isGoods = goodsNum ~= nil
    self._isGoods = isGoods
    self._data    = data
    KTool.SetActive(self.Goods.gameObject,   isGoods)
    KTool.SetActive(self.CatBall.gameObject, not isGoods)
    
    ---如果是道具的话改成 能多次触发选择道具
    self.BtnNode.isRepeating = isGoods
    
    if isGoods then
        ---@type GoodsVo
        local goodsVo = data.vo
        CfUtils.RefeshGoodGo(self.GoodNode, goodsVo.id, string.format("x%s", goodsNum), GoodsScale)
            
        local selectNum = data.selectNum
        self:FreshGoodSelectNum(selectNum)
        self:FreshSelectState(selectNum > 0)
    else
        self:RegEvent()
        local genes = data.catData ~= nil and data.catData.genes or data.vo.kind1
        self:CaptureTexture(data.vo.catId, genes)

        self.ImgQualityBg.Status = data.quality
        
        self:FreshSelectState(playerCatId2Data[data.catData.id])
    end
    
end

function OverseaManageCatBallExchangeCell:FreshGoodSelectNum(goodsSelectNum)
    local isSelect = goodsSelectNum ~= nil and goodsSelectNum > 0
    GameUtils.UpdateUIShowStateByCanvasGroup(self.ChooseQuantityNode, goodsSelectNum ~= nil and goodsSelectNum > 0)
    self.TextNumber.text = goodsSelectNum
    self:FreshSelectState(isSelect)
    
end

function OverseaManageCatBallExchangeCell:RegEvent()
    if self.__EventCaptureTextureCompleteAction then
        return
    end
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end

function OverseaManageCatBallExchangeCell:CaptureTexture(catId, genes)
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, catId, genes)
    self._fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(catId), genes,false, fileNameId)
end


function OverseaManageCatBallExchangeCell:FreshSelectState(isSelect)
    GameUtils.UpdateUIShowStateByCanvasGroup(self.ImgSelect, isSelect)
end


--endregion


--region get/set
function OverseaManageCatBallExchangeCell:SetClickCb(cb)
    self._clickCb = cb
end

function OverseaManageCatBallExchangeCell:SetLongPressCb(cb)
    self._longPressCb = cb
end

function OverseaManageCatBallExchangeCell:SetClickBtnReduceCb(cb)
    self._clickBtnReduceCb = cb
end

function OverseaManageCatBallExchangeCell:SetLongPressBtnReduceCb(cb)
    self._longPressBtnReduceCb = cb
end

--endregion


--region handler

function OverseaManageCatBallExchangeCell:OnEventCaptureTextureCompleteAction(id, path)
    if self._fileNameId ~= id then return end
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    self.ImgCatBallIcon.texture = texture
    KTool.SetActive(self.ImgCatBallIcon.gameObject, true)
end

--endregion

return OverseaManageCatBallExchangeCell